 $manifestInput=Read-T10Input $RunAnchor([IO.Path]::Combine($private,'manifest-input.json'));Assert-T10ManifestInput $manifestInput $RunId $RegistryRepo
 $manifest=[ordered]@{schema='test10a-chrome-run-v1';runId=$manifestInput.runId;createdAt=$manifestInput.createdAt;os=$manifestInput.os;sourceSha256=$manifestInput.sourceSha256;appImage=$manifestInput.appImage;fixtureHash=$manifestInput.fixtureHash;browser=$manifestInput.browser;acceptanceCaseIds=@($manifestInput.acceptanceCaseIds);runScenarioIds=@($manifestInput.runScenarioIds);bindingsSha256=$manifestInput.bindingsSha256;payloadRegistrySha256=$manifestInput.payloadRegistrySha256;observerRegistrySha256=$manifestInput.observerRegistrySha256;evidencePolicySha256=$manifestInput.evidencePolicySha256;cleanupReceipt=$manifestInput.cleanupReceipt;previous1='not_run';previous2='not_run'}
 $bytes=$script:Utf8.GetBytes((ConvertTo-T10CanonicalJson $manifest));$written=Write-T10Once $RunAnchor $evidence 'manifest.json' $bytes;$summary=[ordered]@{schema='test10a-hash-summary-v1';runId=$RunId;manifestFile='manifest.json';manifestBytes=$written.bytes;manifestSha256=$written.sha256};$summaryBytes=$script:Utf8.GetBytes((ConvertTo-T10CanonicalJson $summary));$summaryWritten=Write-T10Once $RunAnchor $evidence 'manifest.sha256.json' $summaryBytes;return ([ordered]@{schema='test10a-writer-result-v1';status='PASS';runId=$RunId;manifestBytes=$written.bytes;manifestSha256=$written.sha256;summaryBytes=$summaryWritten.bytes;summarySha256=$summaryWritten.sha256})
}
function WriteManifest{Assert-T10RunId $RunId;$repo=[IO.Path]::GetFullPath([IO.Path]::Combine($PSScriptRoot,'..'));$runRoot=[IO.Path]::Combine($repo,'work','test10','runs',$RunId);Invoke-T10WriteManifest $repo $repo $runRoot $RunId}
function StaticTest-Inventory([string]$Root,[string]$Directory,[Collections.Generic.List[string]]$Rows){
 foreach($path in [IO.Directory]::GetFileSystemEntries($Directory)){$attributes=[IO.File]::GetAttributes($path);if($attributes-band[IO.FileAttributes]::ReparsePoint){Fail-T10Writer 'TEST_CLEANUP_REPARSE'};$relative=$path.Substring($Root.Length+1).Replace('\','/');$Rows.Add($relative);if($attributes-band[IO.FileAttributes]::Directory){StaticTest-Inventory $Root $path $Rows}}
}
function StaticTest-Cleanup([string]$Root,[string[]]$Expected){
 Assert-T10Ordinary([IO.Path]::GetDirectoryName($Root))$Root $true;$rows=[Collections.Generic.List[string]]::new();StaticTest-Inventory $Root $Root $rows
 $actual=@($rows|Sort-Object);if(($actual-join"`n")-cne(@($Expected|Sort-Object)-join"`n")){Fail-T10Writer 'TEST_CLEANUP'};[IO.Directory]::Delete($Root,$true)
}
function StaticTest-Ast([string]$Path){
 $tokens=$null;$errors=$null;$ast=[Management.Automation.Language.Parser]::ParseFile($Path,[ref]$tokens,[ref]$errors);if($errors.Count){Fail-T10Writer 'AST_PARSE'}
 $functions=@($ast.FindAll({param($node)$node-is[Management.Automation.Language.FunctionDefinitionAst]},$true));$local=@($functions.Name)
 $allowedMembers=@('Create','ComputeHash','Replace','ToLowerInvariant','Dispose','ContainsKey','ToString','GetFullPath','TrimEnd','StartsWith','Equals','GetAttributes','GetDirectoryName','IsNullOrWhiteSpace','GetString','Combine','Split','ReadAllBytes','EndsWith','Open','Write','Flush','Move','GetFileSystemEntries','GetBytes','ParseExact')
 foreach($function in $functions){if($function.Name-like'StaticTest*'){continue};$text=$function.Body.Extent.Text;if($text-match'(?i)Start-Process|Invoke-Expression|Diagnostics\.Process|ProcessStartInfo|::Delete|::Replace|Remove-Item'){Fail-T10Writer 'AST_FORBIDDEN'}
