  foreach($call in @($function.Body.FindAll({param($node)$node-is[Management.Automation.Language.InvokeMemberExpressionAst]},$true))){$member=[string]$call.Member.Value;if($member-cnotin$allowedMembers){Fail-T10Writer 'AST_MEMBER'}}
 }
