}
function StaticTest{
 $assertions=0;$unicode=([string][char]0x042D)+[char]0x0441+[char]0x0442+[char]0x0430+[char]0x043A+[char]0x0430+[char]0x0434+[char]0x0430;$golden='{"ascii":"a/b","control":"line\nquote\"slash\\","integer":42,"unicode":"'+$unicode+'"}';$goldenValue=[ordered]@{ascii='a/b';control=('line'+[char]10+'quote"slash\');integer=42;unicode=$unicode};if((ConvertTo-T10CanonicalJson $goldenValue)-cne$golden){Fail-T10Writer 'GOLDEN_BYTES'};$assertions++;$goldenBytes=$script:Utf8.GetBytes($golden);if($goldenBytes.Length-ne90-or(Get-T10Sha $goldenBytes)-cne'cbd5619165f9dce4242e7991344932eca8879a94f4bfae7efd4fb8e904abc110'){Fail-T10Writer 'GOLDEN_HASH'};$assertions++
