  $policyText=$script:Utf8.GetString([IO.File]::ReadAllBytes([IO.Path]::Combine($repo,'acceptance','test10a-evidence-policy.json')));$policy=$policyText|Microsoft.PowerShell.Utility\ConvertFrom-Json
  $staleNames=@($policy.writeOnceFiles|ForEach-Object{$_;$_.ToString()+'.new'})+@('unknown.bin')
  $staleIndex=0;foreach($staleName in $staleNames){$staleIndex++;$caseRoot=[IO.Path]::Combine($root,'stale-'+$staleIndex);$caseRun=[IO.Path]::Combine($caseRoot,'run');$casePrivate=[IO.Path]::Combine($caseRun,'private');$caseEvidence=[IO.Path]::Combine($caseRun,'evidence');[IO.Directory]::CreateDirectory($casePrivate)|Out-Null;[IO.Directory]::CreateDirectory($caseEvidence)|Out-Null;$stalePath=[IO.Path]::Combine($caseEvidence,$staleName);[IO.File]::WriteAllBytes($stalePath,[byte[]](1,2,3));try{Invoke-T10WriteManifest $caseRoot $repo $caseRun $runId|Out-Null;Fail-T10Writer 'STALE_ACCEPTED'}catch{if($_.Exception.Message-cnotmatch'ROOT_NOT_EMPTY'){throw}};$assertions++;StaticTest-Cleanup $caseRoot @('run','run/private','run/evidence',('run/evidence/'+$staleName))}
